changeSet.sql:
DELETE FROM workspace_agent_binding WHERE purpose IN ('PRACTICE_DECISION','PRACTICE_EMBEDDING','PRACTICE_RERANKING');
DELETE FROM llm_model WHERE connection_id IN (
    SELECT id FROM llm_connection WHERE api_protocol IN ('openai-decisions','openai-embeddings','cohere-rerank'));
DELETE FROM llm_connection WHERE api_protocol IN ('openai-decisions','openai-embeddings','cohere-rerank');

UPDATE review_job
SET config_snapshot = jsonb_set(config_snapshot - 'practiceScript', '{schemaVersion}', '10'::jsonb)
WHERE config_snapshot ->> 'schemaVersion' = '9';
